// FeedServiceHandler is an implementation of the cogfeed.v1.FeedService service.
type FeedServiceHandler interface {
	// --- Browsing ---------------------------------------------------------
	// Sidebar in one call: folders, subscriptions, tags, playlists, counts.
	GetLibrary(context.Context, *connect.Request[feedpb.GetLibraryRequest]) (*connect.Response[feedpb.Library], error)
	// Items of a view (all, unread, starred, history, folder, subscription,
	// tag, playlist) or of a query in Cog's grammar, in server order.
	ListItems(context.Context, *connect.Request[feedpb.ListItemsRequest]) (*connect.Response[feedpb.ListItemsResponse], error)
	GetItem(context.Context, *connect.Request[feedpb.GetItemRequest]) (*connect.Response[feedpb.ItemDetail], error)
	// Validates a query and returns a count and a few matches (the filter
	// editor's live preview).
	PreviewQuery(context.Context, *connect.Request[feedpb.PreviewQueryRequest]) (*connect.Response[feedpb.PreviewQueryResponse], error)
	// --- Item state --------------------------------------------------------
	SetRead(context.Context, *connect.Request[feedpb.SetReadRequest]) (*connect.Response[feedpb.Item], error)
	SetStarred(context.Context, *connect.Request[feedpb.SetStarredRequest]) (*connect.Response[feedpb.Item], error)
	MarkAllRead(context.Context, *connect.Request[feedpb.MarkAllReadRequest]) (*connect.Response[feedpb.MarkAllReadResponse], error)
	SetTags(context.Context, *connect.Request[feedpb.SetTagsRequest]) (*connect.Response[feedpb.Item], error)
	// Client-timestamped; the server keeps the newest by `at`.
	ReportProgress(context.Context, *connect.Request[feedpb.ReportProgressRequest]) (*connect.Response[feedpb.Playback], error)
	// --- Media ---------------------------------------------------------------
	// Where to play an item from, for a variant: Cog's /items/{id}/media for
	// media Cog holds, a resolved stream (with expiry) for a YouTube video it
	// does not, and the origin for any other enclosure. FailedPrecondition
	// when the item has no media.
	ResolveMedia(context.Context, *connect.Request[feedpb.ResolveMediaRequest]) (*connect.Response[feedpb.MediaSource], error)
	// Skip (silence) and mute (profanity) ranges.
	GetRanges(context.Context, *connect.Request[feedpb.GetRangesRequest]) (*connect.Response[feedpb.Ranges], error)
	// Ask the server to download (and run its pipeline on) an item.
	RequestDownload(context.Context, *connect.Request[feedpb.RequestDownloadRequest]) (*connect.Response[feedpb.DownloadState], error)
	GetPlayerPrefs(context.Context, *connect.Request[feedpb.GetPlayerPrefsRequest]) (*connect.Response[feedpb.PlayerPrefs], error)
	SetPlayerPrefs(context.Context, *connect.Request[feedpb.PlayerPrefs]) (*connect.Response[feedpb.PlayerPrefs], error)
	// --- Sync ----------------------------------------------------------------
	// Everything that changed since a token. Empty token = full snapshot.
	Changes(context.Context, *connect.Request[feedpb.ChangesRequest]) (*connect.Response[feedpb.ChangesResponse], error)
	// Server streaming: pushes a token whenever something changes, so a client
	// calls Changes promptly instead of polling. Ends on server shutdown.
	Watch(context.Context, *connect.Request[feedpb.WatchRequest], *connect.ServerStream[feedpb.WatchEvent]) error
	// --- Management (web parity) -----------------------------------------------
	AddSubscription(context.Context, *connect.Request[feedpb.AddSubscriptionRequest]) (*connect.Response[feedpb.Subscription], error)
	UpdateSubscription(context.Context, *connect.Request[feedpb.UpdateSubscriptionRequest]) (*connect.Response[feedpb.Subscription], error)
	DeleteSubscription(context.Context, *connect.Request[feedpb.DeleteSubscriptionRequest]) (*connect.Response[feedpb.DeleteResponse], error)
	RefreshSubscription(context.Context, *connect.Request[feedpb.RefreshSubscriptionRequest]) (*connect.Response[feedpb.Subscription], error)
	SaveFolder(context.Context, *connect.Request[feedpb.Folder]) (*connect.Response[feedpb.Folder], error)
	DeleteFolder(context.Context, *connect.Request[feedpb.DeleteFolderRequest]) (*connect.Response[feedpb.DeleteResponse], error)
	ListFilters(context.Context, *connect.Request[feedpb.ListFiltersRequest]) (*connect.Response[feedpb.ListFiltersResponse], error)
	SaveFilter(context.Context, *connect.Request[feedpb.Filter]) (*connect.Response[feedpb.Filter], error)
	DeleteFilter(context.Context, *connect.Request[feedpb.DeleteFilterRequest]) (*connect.Response[feedpb.DeleteResponse], error)
	SavePlaylist(context.Context, *connect.Request[feedpb.Playlist]) (*connect.Response[feedpb.Playlist], error)
	DeletePlaylist(context.Context, *connect.Request[feedpb.DeletePlaylistRequest]) (*connect.Response[feedpb.DeleteResponse], error)
	Import(context.Context, *connect.Request[feedpb.ImportRequest]) (*connect.Response[feedpb.ImportResponse], error)
	ExportOPML(context.Context, *connect.Request[feedpb.ExportOPMLRequest]) (*connect.Response[feedpb.ExportOPMLResponse], error)
}

